 function buildAdminOrderMove(items=[],rows=[],offerId,direction){const normalizedDirection=text(direction).toLowerCase();if(!["up","down"].includes(normalizedDirection))throw new Error("Admin display order direction must be up or down.");const snapshot=buildAdminOrderSnapshot(items,rows),exactOfferId=text(offerId),index=snapshot.findIndex(row=>row.offer_id===exactOfferId);if(index<0)throw new Error(`Exact offer ${exactOfferId||"unknown"} is not in the Admin Fleet order.`);const targetIndex="up"===normalizedDirection?index-1:index+1;if(targetIndex<0||targetIndex>=snapshot.length)return Object.freeze({moved:!1,expectedRows:snapshot,orderedOfferIds:snapshot.map(row=>row.offer_id)});const orderedOfferIds=snapshot.map(row=>row.offer_id);return[orderedOfferIds[index],orderedOfferIds[targetIndex]]=[orderedOfferIds[targetIndex],orderedOfferIds[index]],Object.freeze({moved:!0,exactOfferId:exactOfferId,targetOfferId:snapshot[targetIndex].offer_id,expectedRows:snapshot,orderedOfferIds:orderedOfferIds})}export function getAdminOrderControlState(index,total,enabled=!0,busy=!1){const safeIndex=finiteInteger(index,-1),safeTotal=finiteInteger(total,0),interactive=!0===enabled&&!0!==busy&&safeIndex>=0&&safeIndex<safeTotal;return Object.freeze({upDisabled:!interactive||0===safeIndex,downDisabled:!interactive||safeIndex===safeTotal-1})}export function hasCompleteAdminOrder(items=[],rows=[]){try{return buildAdminOrderSnapshot(items,rows).length===(Array.isArray(items)?items.length:0)}catch(_){return!1}}